import streamlit as st
import pandas as pd
import numpy as np
import joblib
import warnings
warnings.filterwarnings("ignore")

# ── Page config ────────────────────────────────────────────────────────────────
st.set_page_config(
    page_title="CatBoost Adsorption Predictor",
    page_icon="🌿",
    layout="wide",
    initial_sidebar_state="expanded",
)

# ══════════════════════════════════════════════════════════════════════════════
# Williams-plot / leverage (applicability-domain) helpers — INLINE.
# NOTE: identical design-matrix logic (_one_hot / _build_design_matrix) also
# lives in CatBoost_Package.py, which is what fit XtX_inv / h_star in the
# first place. If you ever change the math here, copy the change there too —
# otherwise a new sample gets scored against a different design matrix than
# the one the training leverages were computed on.
# ══════════════════════════════════════════════════════════════════════════════

def _one_hot(df, col, categories):
    cat = pd.Categorical(df[col].astype(str), categories=categories)
    return pd.get_dummies(cat, prefix=col)

def _build_design_matrix(df, numerical_cols, categorical_cols, cat_categories,
                          scaler_mean, scaler_scale):
    num = df[numerical_cols].astype(float).values
    num_scaled = (num - scaler_mean) / scaler_scale
    dummy_blocks = [
        _one_hot(df, c, cat_categories[c]).values.astype(float)
        for c in categorical_cols
    ]
    intercept = np.ones((len(df), 1))
    return np.hstack([intercept, num_scaled] + dummy_blocks)

def compute_leverage(row_df, leverage_artifacts):
    """row_df: 1-row DataFrame with the raw input feature values."""
    x = _build_design_matrix(
        row_df,
        leverage_artifacts['numerical_cols'],
        leverage_artifacts['categorical_cols'],
        leverage_artifacts['cat_categories'],
        leverage_artifacts['scaler_mean'],
        leverage_artifacts['scaler_scale'],
    )
    return float(x @ leverage_artifacts['XtX_inv'] @ x.T)

def classify_confidence(h, h_star, medium_multiplier=3.0):
    """
    High   : h <= h*                        (inside the training domain)
    Medium : h*  < h <= medium_multiplier*h* (borderline extrapolation)
    Low    : h  > medium_multiplier*h*       (well outside training domain)
    """
    if h <= h_star:
        return "High"
    elif h <= medium_multiplier * h_star:
        return "Medium"
    else:
        return "Low"

def note_box(text):
    """Plain black-text note box — used for all prediction sanity-check
    messages (negative Qe, exceeds theoretical max, within range), so none
    of them carry Streamlit's built-in red/orange/blue coloring."""
    st.markdown(
        f"""
        <div style="background:#f0f0f0; border-left:4px solid #999;
                    border-radius:6px; padding:10px 14px;
                    color:#000; font-size:14px; margin-top:8px;">
            {text}
        </div>
        """,
        unsafe_allow_html=True,
    )

