# ══════════════════════════════════════════════════════════════════════════════
# LOAD PACKAGE
# ══════════════════════════════════════════════════════════════════════════════
PKG_PATH = "CatBoost_package.pkl"

@st.cache_resource(show_spinner="Loading CatBoost model…")
def load_package(path):
    return joblib.load(path)

try:
    pkg = load_package(PKG_PATH)
except FileNotFoundError:
    st.error(f"**Package not found:** `{PKG_PATH}` — run `CatBoost_Package.py` first.")
    st.stop()

model              = pkg['model']
feature_names      = pkg['feature_names']
categorical_cols   = pkg['categorical_cols']
numerical_cols     = pkg['numerical_cols']
biomass_values     = pkg['biomass_values']
pollutant_values   = pkg['pollutant_values']
cv_results         = pkg['cv_results']
train_metrics_f    = pkg['train_metrics_final']
test_metrics_f     = pkg['test_metrics_final']
oof_preds          = pkg['oof_preds']
oof_actuals        = pkg['oof_actuals']
y_train_arr        = pkg['y_train']
train_preds_final  = pkg['train_preds_final']
y_test_arr         = pkg['y_test']
test_preds_final   = pkg['test_preds_final']
feat_importances   = pkg['feat_importances']

leverage_artifacts = pkg['leverage']
h_star             = leverage_artifacts['h_star']
X_train_raw        = pkg['X_train']          # imputed training rows, for Random Sample

# Column names for the theoretical-maximum sanity check (Qe <= C0/Dosage).
# Read from the package rather than hardcoded, so a future retrain with
# renamed columns can't silently mismatch here.
CONC_COL   = pkg['conc_col']
DOSAGE_COL = pkg['dosage_col']

# ── Feature groupings, by explicit name (not index slice — index slices
# silently break if the spreadsheet's column order ever changes; this
# doesn't). Based on your actual header:
#   Biomass, Pyrolysis temperature, Pyrolysis time, Pyrolysis rate, Ash,
#   C, N, O, H, Biochar pH, O/C, H/C, Sa, Pore volume, Pollutant,
#   Initial concentration, St, Solution pH, Dosage, Reaction time
# (Titles and Qe (mg/g) are already excluded before feature_names is built.)
CATEGORY1_FEATURES = [
    'Biomass', 'Pyrolysis temperature (℃)', 'Pyrolysis time (h)',
    'Pyrolysis rate (℃/min)',
]
CATEGORY2_FEATURES = [
    'Ash (%)', 'C (%)', 'N (%)', 'O (%)', 'H (%)', 'Biochar pH',
    'O/C', 'H/C', 'Sa (m²/g)', 'Pore volume (cm³/g)',
]
CATEGORY3_FEATURES = [
    'Pollutant', 'Initial concentration (mg/L)', 'St (℃)', 'Solution pH',
    'Dosage (g/L)', 'Reaction time (h)',
]

# Sanity check: every feature must land in exactly one group, and nothing
# should be missing or duplicated — fail loudly at startup instead of
# silently mis-grouping a feature (or silently omitting one from the form).
_all_grouped = CATEGORY1_FEATURES + CATEGORY2_FEATURES + CATEGORY3_FEATURES
assert sorted(_all_grouped) == sorted(feature_names), (
    f"Feature grouping mismatch — check CATEGORY1/2/3_FEATURES against the "
    f"actual columns. Missing: {set(feature_names) - set(_all_grouped)} | "
    f"Unexpected: {set(_all_grouped) - set(feature_names)}"
)

GROUPS = {
    "🔥 Pyrolysis Conditions":    CATEGORY1_FEATURES,
    "🧬 Biochar Characteristics": CATEGORY2_FEATURES,
    "⚗️  Adsorption Conditions":  CATEGORY3_FEATURES,
}
GROUP_CLASSES = {
    "🔥 Pyrolysis Conditions":    "cat1",
    "🧬 Biochar Characteristics": "cat2",
    "⚗️  Adsorption Conditions":  "cat3",
}

C_COL  = 'C (%)'
H_COL  = 'H (%)'
O_COL  = 'O (%)'
HC_COL = 'H/C'
OC_COL = 'O/C'
AUTO_COMPUTED = {HC_COL, OC_COL}

CONF_COLORS = {"High": "#2b9c8f", "Medium": "#e0a800", "Low": "#c0392b"}

# ══════════════════════════════════════════════════════════════════════════════
# SIDEBAR
# ══════════════════════════════════════════════════════════════════════════════
with st.sidebar:
    st.markdown("## 🌿 CatBoost Predictor")
    st.markdown("---")
    st.markdown("**Model:** CatBoostRegressor")
    st.markdown(f"**Features:** {len(feature_names)}")
    st.markdown(f"**Categoricals:** {', '.join(categorical_cols)}")
    st.markdown("---")

    st.markdown("### 📊 Model Performance")
    r2_v  = cv_results['R2']['val_mean']
    r2_vs = cv_results['R2']['val_std']
    r2_t  = test_metrics_f['R2']
    rmse_v  = cv_results['RMSE']['val_mean']
    rmse_vs = cv_results['RMSE']['val_std']
    rmse_t  = test_metrics_f['RMSE']
    st.markdown(f"**R² Validation:** {r2_v:.4f} ± {r2_vs:.4f}")
    st.markdown(f"**R² Test:**        {r2_t:.4f}")
    st.markdown(f"**RMSE Validation:** {rmse_v:.4f} ± {rmse_vs:.4f}")
    st.markdown(f"**RMSE Test:**       {rmse_t:.4f}")
    st.markdown("---")

    st.markdown("### ℹ️ How to use")
    st.markdown(
        "1. Fill in feature values below\n"
        "2. H/C and O/C update automatically\n"
        "3. Press **Predict** to get Qe\n"
        "4. Use **Random Sample** to explore"
    )
    st.markdown("---")

    if st.button("🎲 Fill Random Sample", key="rand_btn", use_container_width=True):
        # Draw one REAL row from the (imputed) training set — not
        # independently randomized per-feature — so the sample reflects an
        # actual, plausible combination.
        sample_row = X_train_raw.sample(n=1).iloc[0]
        for f in feature_names:
            if f in AUTO_COMPUTED:
                continue  # H/C and O/C recompute live from C/H/O
            val = sample_row[f]
            if f in categorical_cols:
                st.session_state[f'inp_{f}'] = str(val)
            else:
                st.session_state[f'inp_{f}'] = round(float(val), 4)
        st.rerun()

# ══════════════════════════════════════════════════════════════════════════════
# PAGE HEADER
# ══════════════════════════════════════════════════════════════════════════════
st.markdown(
    '<p class="page-title">🌿 Biochar Adsorption Capacity Predictor</p>'
    '<p class="page-subtitle">Predict equilibrium adsorption capacity '
    '<b>Qe (mg/g)</b> using a CatBoost model with native categorical support '
    'and Optuna-tuned hyperparameters.</p>',
    unsafe_allow_html=True
)
st.markdown("---")

# ══════════════════════════════════════════════════════════════════════════════
# INPUT FORM
# ══════════════════════════════════════════════════════════════════════════════
input_vals = {}
form_cols  = st.columns(len(GROUPS))

for col_obj, (group_name, group_features) in zip(form_cols, GROUPS.items()):
    cls = GROUP_CLASSES[group_name]
    with col_obj:
        st.markdown(
            f'<div class="card">'
            f'<div class="card-title {cls}-title">{group_name}</div>',
            unsafe_allow_html=True,
        )

        for feat in group_features:

            if feat == 'Biomass':
                cur = st.session_state.get(f'inp_{feat}', biomass_values[0])
                idx = biomass_values.index(cur) if cur in biomass_values else 0
                val = st.selectbox("Biomass", biomass_values, index=idx,
                                   key=f'inp_{feat}',
                                   help="Feedstock type used to produce biochar")
                input_vals[feat] = val

            elif feat == 'Pollutant':
                cur = st.session_state.get(f'inp_{feat}', pollutant_values[0])
                idx = pollutant_values.index(cur) if cur in pollutant_values else 0
                val = st.selectbox("Pollutant", pollutant_values, index=idx,
                                   key=f'inp_{feat}',
                                   help="Target pollutant for adsorption")
                input_vals[feat] = val

            elif feat in AUTO_COMPUTED:
                c_now = float(st.session_state.get(f'inp_{C_COL}', 0.0) or 0.0)
                h_now = float(st.session_state.get(f'inp_{H_COL}', 0.0) or 0.0)
                o_now = float(st.session_state.get(f'inp_{O_COL}', 0.0) or 0.0)

                if feat == HC_COL:
                    live_val = round(h_now / c_now, 4) if c_now > 0 else 0.0
                else:
                    live_val = round(o_now / c_now, 4) if c_now > 0 else 0.0

                st.markdown(
                    f'<div class="ratio-box">'
                    f'<div class="ratio-label">{feat} &nbsp;(auto-calculated)</div>'
                    f'<div class="ratio-value">{live_val:.4f}</div>'
                    f'</div>',
                    unsafe_allow_html=True
                )
                input_vals[feat] = live_val

            else:
                val = st.number_input(
                    feat,
                    value=float(st.session_state.get(f'inp_{feat}', 0.0)),
                    format="%.4f",
                    key=f'inp_{feat}'
                )
                input_vals[feat] = val

        st.markdown('</div>', unsafe_allow_html=True)

# Sync ratios for prediction
c_val = float(input_vals.get(C_COL, 0.0) or 0.0)
h_val = float(input_vals.get(H_COL, 0.0) or 0.0)
o_val = float(input_vals.get(O_COL, 0.0) or 0.0)
input_vals[HC_COL] = round(h_val / c_val, 4) if c_val > 0 else 0.0
input_vals[OC_COL] = round(o_val / c_val, 4) if c_val > 0 else 0.0

# Theoretical-maximum Qe = C0 / Dosage (all pollutant removed from solution)
conc_val   = float(input_vals.get(CONC_COL,   0.0) or 0.0)
dosage_val = float(input_vals.get(DOSAGE_COL, 0.0) or 0.0)
qe_theoretical_max = (conc_val / dosage_val) if dosage_val > 0 else None

# ══════════════════════════════════════════════════════════════════════════════
# PREDICT BUTTON
# ══════════════════════════════════════════════════════════════════════════════
st.markdown("")
_, btn_col, _ = st.columns([1, 2, 1])
with btn_col:
    predict_clicked = st.button("⚡ Predict Qe (mg/g)", key="predict_btn")

# ══════════════════════════════════════════════════════════════════════════════
# RESULT
# ══════════════════════════════════════════════════════════════════════════════
if predict_clicked:
    errors = []
    numeric_vals = [v for k, v in input_vals.items()
                    if k not in categorical_cols and isinstance(v, (int, float))]
    if any(v < 0 for v in numeric_vals):
        errors.append("All numeric inputs must be ≥ 0.")
    if c_val <= 0:
        errors.append("C (%) must be > 0 to compute H/C and O/C ratios.")
    if dosage_val <= 0:
        errors.append(f"{DOSAGE_COL} must be > 0 to check the theoretical maximum Qe.")

    if errors:
        for e in errors:
            st.error(f"❌ {e}")
    else:
        with st.spinner("Running CatBoost model…"):
            try:
                row = pd.DataFrame([input_vals])
                for col in categorical_cols:
                    row[col] = row[col].astype(str)
                row = row[feature_names]
                qe  = float(model.predict(row)[0])

                # ── Williams leverage / confidence ────────────────────────────
                h = compute_leverage(row, leverage_artifacts)
                confidence = classify_confidence(h, h_star)
                conf_color = CONF_COLORS[confidence]
                # ───────────────────────────────────────────────────────────────

                _, res_col, _ = st.columns([1, 2, 1])
                with res_col:
                    # Negative Qe is physically meaningless (adsorption
                    # capacity can't go below zero), so don't display the
                    # raw negative number as if it were a real result — the
                    # note box below explains why instead.
                    displayed_qe = f"{qe:.2f}" if qe >= 0 else "—"
                    st.markdown(
                        f"""
                        <div class="result-box">
                            <div class="result-label">Predicted Equilibrium Adsorption Capacity</div>
                            <div class="result-value">{displayed_qe}</div>
                            <div class="result-unit">mg / g</div>
                            <div class="result-sub">CatBoost · Optuna-tuned · 5-fold Nested CV</div>
                            <div style="margin-top:14px; padding-top:10px; border-top:1px solid rgba(255,255,255,0.25);">
                                <span style="font-size:13px; opacity:.75;">Reliability (Williams leverage)</span><br>
                                <span style="font-size:22px; font-weight:800; color:{conf_color};">{confidence} Confidence</span><br>
                                <span style="font-size:12px; opacity:.6;">h = {h:.4f} &nbsp;|&nbsp; h* = {h_star:.4f}</span>
                            </div>
                        </div>
                        """,
                        unsafe_allow_html=True,
                    )

                    # ── Negative-prediction sanity check ──────────────────────
                    # Qe (adsorption capacity) cannot physically be negative —
                    # that would mean the biochar released more pollutant than
                    # it captured. CatBoost has no built-in constraint forcing
                    # Qe >= 0, so a bad extrapolation can output a negative
                    # number. The raw value is hidden above (shown as "—")
                    # rather than displayed as if it were a real result.
                    if qe < 0:
                        note_box(
                            "The model's raw prediction was negative, which "
                            "isn't physically possible for adsorption "
                            "capacity. Please be cautious about using this "
                            "result."
                        )
                    # ── Theoretical-maximum sanity check ──────────────────────
                    # Qe cannot physically exceed C0/Dosage — that would mean
                    # more pollutant was removed than was present in solution
                    # to begin with. NOTE: this is a separate, independent
                    # check from the Williams-leverage confidence above — a
                    # prediction can exceed this physical bound even when
                    # leverage says "High Confidence" (leverage only measures
                    # how similar the INPUT is to training rows; it says
                    # nothing about whether this specific output is
                    # physically sane). So we don't re-claim "outside the
                    # training domain" here — just flag it plainly.
                    elif qe_theoretical_max is not None and qe > qe_theoretical_max:
                        note_box(
                            f"Predicted Qe ({qe:.2f} mg/g) exceeds the "
                            f"theoretical max of {qe_theoretical_max:.2f} mg/g "
                            f"(C₀/Dosage). Please be cautious about using "
                            f"this result."
                        )
                    elif qe_theoretical_max is not None:
                        note_box(
                            f"Predicted Qe ({qe:.2f} mg/g) is within the "
                            f"theoretical max of {qe_theoretical_max:.2f} mg/g "
                            f"(C₀/Dosage)."
                        )

            except Exception as ex:
                st.error(f"⚠️ Prediction failed: {ex}")
                st.exception(ex)

# ══════════════════════════════════════════════════════════════════════════════
# PERFORMANCE METRICS
# ══════════════════════════════════════════════════════════════════════════════
st.markdown("---")
st.markdown("#### Nested CV + Held-out Test Metrics")

key_metrics = ['R2', 'AR2', 'EVS', 'RMSE', 'MAE', 'MAPE', 'SMAPE', 'RSR', 'CVRMSE', 'RAE']
rows = []
for mn in key_metrics:
    r = cv_results[mn]
    rows.append({
        'Metric'          : mn,
        'Train (mean)'    : f"{r['train_mean']:.4f}",
        'Train (± std)'   : f"± {r['train_std']:.4f}",
        'Val (mean)'      : f"{r['val_mean']:.4f}",
        'Val (± std)'     : f"± {r['val_std']:.4f}",
        'Test (held-out)' : f"{test_metrics_f[mn]:.4f}",
    })
st.dataframe(pd.DataFrame(rows).set_index('Metric'), use_container_width=True)

# Summary cards for key metrics
st.markdown("#### Key Metric Cards")
card_metrics = ['R2', 'RMSE', 'MAE', 'SMAPE']
cols = st.columns(len(card_metrics))
for col_obj, mn in zip(cols, card_metrics):
    r = cv_results[mn]
    with col_obj:
        st.markdown(
            f'<div class="metric-card">'
            f'<div class="metric-label">{mn}</div>'
            f'<div class="metric-val">{r["val_mean"]:.4f}</div>'
            f'<div class="metric-std">± {r["val_std"]:.4f} (val) &nbsp;|&nbsp; '
            f'{test_metrics_f[mn]:.4f} (test)</div>'
            f'</div>',
            unsafe_allow_html=True
        )

# ══════════════════════════════════════════════════════════════════════════════
# FOOTER
# ══════════════════════════════════════════════════════════════════════════════
st.markdown("---")
st.markdown(
    "<p style='text-align:center; color:#888; font-size:13px;'>"
    "CatBoostRegressor · Optuna HPO · 5-fold Nested CV · "
    "Zero Data Leakage · Train / Val / Test split</p>",
    unsafe_allow_html=True,
)
